<?php
require_once __DIR__ . '/../includes/auth.php';
auth_require_roles(['Administrador','Tecnico']);
$mensaje=''; $error='';
$tipos=['Instalación','Capacitación','Reparación','Mantenimiento','Soporte técnico','Otro'];
$estados=['Pendiente','En revisión','Finalizado'];
if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (!csrf_valid()) $error='La sesión del formulario venció. Recarga la página.';
    else {
        $accion=$_POST['accion'] ?? '';
        if ($accion==='crear') {
            $cliente=trim($_POST['cliente_nombre'] ?? ''); $telefono=trim($_POST['cliente_telefono'] ?? '');
            $equipo=trim($_POST['equipo'] ?? ''); $modelo=trim($_POST['modelo'] ?? ''); $tipo=$_POST['tipo_servicio'] ?? 'Reparación';
            $descripcion=trim($_POST['descripcion'] ?? ''); $diagnostico=trim($_POST['diagnostico'] ?? '');
            $costoRaw=trim($_POST['costo'] ?? ''); $costo=$costoRaw===''?null:filter_var($costoRaw,FILTER_VALIDATE_FLOAT);
            if ($cliente==='' || $equipo==='' || $descripcion==='' || !in_array($tipo,$tipos,true) || ($costoRaw!=='' && ($costo===false || $costo<0))) $error='Completa cliente, equipo, tipo y descripción. El costo debe ser cero o positivo.';
            else {
                try {
                    $q=$pdo->prepare('INSERT INTO servicios (cliente_nombre,cliente_telefono,equipo,modelo,tipo_servicio,descripcion,diagnostico,costo,id_usuario) VALUES (?,?,?,?,?,?,?,?,?)');
                    $q->execute([$cliente,$telefono!==''?$telefono:null,$equipo,$modelo!==''?$modelo:null,$tipo,$descripcion,$diagnostico!==''?$diagnostico:null,$costo,(int)auth_user()['id_usuario']]);
                    $id=(int)$pdo->lastInsertId(); $codigo='SRV-'.date('Ymd').'-'.str_pad((string)$id,5,'0',STR_PAD_LEFT);
                    $u=$pdo->prepare('UPDATE servicios SET codigo_servicio=? WHERE id=?');$u->execute([$codigo,$id]);
                    $mensaje='Servicio '.$codigo.' registrado correctamente.'; $_SESSION['csrf_token']=bin2hex(random_bytes(32));
                } catch (Throwable $e) { $error='No se pudo registrar el servicio. Comprueba que hayas importado el SQL actualizado.'; }
            }
        } elseif ($accion==='estado') {
            $id=filter_var($_POST['id'] ?? null,FILTER_VALIDATE_INT); $estado=$_POST['estado'] ?? '';
            if (!$id || !in_array($estado,$estados,true)) $error='Datos de actualización no válidos.';
            else {
                try {
                    $fechaCierre=$estado==='Finalizado'?date('Y-m-d H:i:s'):null;
                    $q=$pdo->prepare('UPDATE servicios SET estado=?, fecha_cierre=? WHERE id=?');$q->execute([$estado,$fechaCierre,$id]);
                    $mensaje='Estado del servicio actualizado.';
                } catch (Throwable $e) { $error='No se pudo actualizar el estado del servicio.'; }
            }
        }
    }
}
$buscar=trim($_GET['buscar'] ?? ''); $estadoFiltro=$_GET['estado'] ?? '';
$sqlq='SELECT * FROM servicios WHERE 1=1';$params=[];
if($buscar!==''){$sqlq.=' AND (codigo_servicio LIKE ? OR cliente_nombre LIKE ? OR equipo LIKE ? OR modelo LIKE ?)';$like='%'.$buscar.'%';array_push($params,$like,$like,$like,$like);}
if(in_array($estadoFiltro,$estados,true)){$sqlq.=' AND estado=?';$params[]=$estadoFiltro;}
$sqlq.=' ORDER BY fecha_ingreso DESC LIMIT 100';$q=$pdo->prepare($sqlq);$q->execute($params);$servicios=$q->fetchAll();
$total=(int)$pdo->query('SELECT COUNT(*) FROM servicios')->fetchColumn();
$pendientes=(int)$pdo->query("SELECT COUNT(*) FROM servicios WHERE estado='Pendiente'")->fetchColumn();
$revision=(int)$pdo->query("SELECT COUNT(*) FROM servicios WHERE estado='En revisión'")->fetchColumn();
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>CONCE SUR | Servicios</title><link rel="stylesheet" href="../css/style.css"><style>
body{background:#0b1120;color:#e5e7eb}.main{min-width:0}.topbar p,.muted{color:#9ca3af}.stats,.bar,.filters,.actions{display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin-bottom:17px}.stats{justify-content:flex-start}.stat{background:#111827;border:1px solid #273449;padding:14px 18px;border-radius:10px;min-width:150px}.stat span{display:block;color:#9ca3af;font-size:12px}.stat strong{font-size:24px;display:block;margin-top:4px}.panel{background:#111827;border:1px solid #273449;border-radius:12px;padding:18px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.field{display:flex;flex-direction:column;gap:7px}.field.full{grid-column:1/-1}.field label{font-size:12px;color:#cbd5e1}.field input,.field select,.field textarea,.filters input,.filters select{background:#0b1120;color:#e5e7eb;border:1px solid #374151;border-radius:7px;padding:11px;font:inherit}.field textarea{min-height:80px}.btn{display:inline-block;border:0;border-radius:8px;padding:11px 15px;font-weight:600;cursor:pointer;text-decoration:none;font-size:13px}.primary{background:#2563eb;color:#fff}.secondary{background:#263244;color:#e5e7eb}.notice{padding:12px 14px;border-radius:8px;margin-bottom:15px}.success{background:#064e3b;color:#a7f3d0}.error{background:#7f1d1d;color:#fecaca}.filters input{flex:1;min-width:180px}.wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:11px;border-bottom:1px solid #273449;vertical-align:top}th{color:#9ca3af}td form{display:flex;gap:6px;align-items:center}td select{max-width:125px;background:#0b1120;color:#e5e7eb;border:1px solid #374151;padding:7px;border-radius:6px}.pill{display:inline-block;padding:4px 8px;border-radius:6px;background:#374151;font-size:12px}.p-pending{background:#78350f;color:#fde68a}.p-review{background:#1e3a8a;color:#bfdbfe}.p-done{background:#065f46;color:#a7f3d0}.muted{font-size:12px;margin-top:10px}@media(max-width:650px){.grid{grid-template-columns:1fr}.field.full{grid-column:auto}}
</style></head><body><div class="app"><?php auth_render_sidebar('servicios'); ?><main class="main"><header class="topbar"><div><h2>Servicios y mantenimiento</h2><p>Registro y seguimiento de instalaciones, capacitaciones y reparaciones</p></div><?php auth_render_user_badge(); ?></header>
<?php if($mensaje):?><div class="notice success"><?=h($mensaje)?></div><?php endif;?><?php if($error):?><div class="notice error"><?=h($error)?></div><?php endif;?>
<section class="stats"><div class="stat"><span>Servicios registrados</span><strong><?=number_format($total)?></strong></div><div class="stat"><span>Pendientes</span><strong><?=number_format($pendientes)?></strong></div><div class="stat"><span>En revisión</span><strong><?=number_format($revision)?></strong></div></section>
<section class="panel" id="nuevo"><h3 style="margin-bottom:5px">Registrar servicio</h3><p class="muted" style="margin-bottom:16px">Registra la atención y actualiza su estado durante el proceso.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=h($_SESSION['csrf_token'])?>"><input type="hidden" name="accion" value="crear"><div class="grid"><div class="field"><label>Cliente *</label><input name="cliente_nombre" maxlength="160" required placeholder="Nombre o razón social"></div><div class="field"><label>Teléfono</label><input name="cliente_telefono" maxlength="30" placeholder="Número de contacto"></div><div class="field"><label>Equipo *</label><input name="equipo" maxlength="160" required placeholder="Ej. Fotocopiadora Ricoh"></div><div class="field"><label>Modelo / serie</label><input name="modelo" maxlength="120" placeholder="Modelo o número de serie"></div><div class="field"><label>Tipo de servicio *</label><select name="tipo_servicio"><?php foreach($tipos as $t):?><option value="<?=h($t)?>"><?=h($t)?></option><?php endforeach;?></select></div><div class="field"><label>Costo estimado (S/)</label><input type="number" min="0" step="0.01" name="costo" placeholder="Opcional"></div><div class="field full"><label>Problema o trabajo solicitado *</label><textarea name="descripcion" maxlength="1000" required placeholder="Describe la falla, instalación o capacitación solicitada"></textarea></div><div class="field full"><label>Diagnóstico inicial (opcional)</label><textarea name="diagnostico" maxlength="1000" placeholder="Observaciones de la revisión inicial"></textarea></div></div><div class="actions" style="margin-top:14px;justify-content:flex-start"><button class="btn primary" type="submit">Guardar servicio</button><a class="btn secondary" href="#lista">Ver servicios</a></div></form></section>
<section class="panel" id="lista"><div class="bar"><div><h3>Historial de servicios</h3><p class="muted">Se muestran hasta 100 registros, desde el más reciente.</p></div></div><form method="get" class="filters"><input name="buscar" value="<?=h($buscar)?>" placeholder="Buscar por código, cliente, equipo o modelo"><select name="estado"><option value="">Todos los estados</option><?php foreach($estados as $e):?><option value="<?=h($e)?>" <?=$estadoFiltro===$e?'selected':''?>><?=h($e)?></option><?php endforeach;?></select><button class="btn primary">Filtrar</button><a class="btn secondary" href="servicios.php">Limpiar</a></form><div class="wrap"><table><thead><tr><th>Código / fecha</th><th>Cliente</th><th>Equipo</th><th>Tipo</th><th>Solicitud / diagnóstico</th><th>Estado y actualización</th></tr></thead><tbody><?php if(!$servicios):?><tr><td colspan="6">No hay servicios registrados con esos filtros.</td></tr><?php else:foreach($servicios as $s):?><tr><td><strong><?=h($s['codigo_servicio'] ?: 'SRV')?></strong><br><span class="muted"><?=h(date('d/m/Y H:i',strtotime($s['fecha_ingreso'])))?></span></td><td><?=h($s['cliente_nombre'])?><br><span class="muted"><?=h($s['cliente_telefono'] ?: 'Sin teléfono')?></span></td><td><?=h($s['equipo'])?><br><span class="muted"><?=h($s['modelo'] ?: 'Modelo no indicado')?></span></td><td><?=h($s['tipo_servicio'])?></td><td><?=h($s['descripcion'])?><?php if($s['diagnostico']):?><br><span class="muted">Diagnóstico: <?=h($s['diagnostico'])?></span><?php endif;?><?php if($s['solucion']):?><br><span class="muted">Solución: <?=h($s['solucion'])?></span><?php endif;?></td><td><span class="pill <?=$s['estado']==='Pendiente'?'p-pending':($s['estado']==='En revisión'?'p-review':'p-done')?>"><?=h($s['estado'])?></span><form method="post" style="margin-top:8px"><input type="hidden" name="csrf_token" value="<?=h($_SESSION['csrf_token'])?>"><input type="hidden" name="accion" value="estado"><input type="hidden" name="id" value="<?=h($s['id'])?>"><select name="estado" aria-label="Cambiar estado"><?php foreach($estados as $e):?><option value="<?=h($e)?>" <?=$s['estado']===$e?'selected':''?>><?=h($e)?></option><?php endforeach;?></select><button class="btn secondary" style="padding:7px 9px">Actualizar</button></form></td></tr><?php endforeach;endif;?></tbody></table></div></section><p class="muted">La trazabilidad fotográfica del antes y después no está implementada todavía; no adjuntes ni afirmes que existen fotos vinculadas hasta desarrollar esa función.</p>
</main></div></body></html>
